--银行自定义配置表增加“支付类型”字段
declare v_count number;
v_str varchar2(1000);
begin
  select count(*)
    into v_count
    from user_tab_columns
   where table_name = 'BT_BANK_TYPE_CUSTOM'
     and column_name = 'BANK_PAY_TYPE';
  if v_count < 1 then
    EXECUTE IMMEDIATE 'alter table BT_BANK_TYPE_CUSTOM add BANK_PAY_TYPE VARCHAR2(500)';
    EXECUTE IMMEDIATE 'comment on column BT_BANK_TYPE_CUSTOM.BANK_PAY_TYPE is ''支付类型''';
  end if;
end;
