--查看该表中该国际化是否存在
SELECT COUNT(*) INTO v_COUNT FROM sys_multi_lang
    WHERE LANG_KEY = 'foreign.message.tranAmt2.eq.payMoney' and LANG_CODE = 'zh_CN';
--如果小于1则说明不存在，则新增国际化
IF v_COUNT < 1 THEN

     insert into sys_multi_lang (ID, LANG_CODE, LANG_CONTEXT, LANG_KEY)
values ('88465b514c804377841ea1498b0f4338', 'zh_CN', '相应金额1必须小于拆分金额', 'foreign.message.tranAmt2.eq.payMoney' );
END IF;
commit;
END;
/

